/** Casa cheia e sem presença gravada: o formulário deixa de confirmar e passa
    a inscrever na fila. Só nome e telefone — o resto se combina quando a vaga sai. */
function modoEspera(){ return capacidade.esgotado && !jaConfirmado; }

function atualizarTrava(){
  /* Confirmou uma vez, acabou: alterar ou cancelar é só por solicitação
     à organização — a página não edita nem exclui nada. */
  const espera = modoEspera();
  const naFila = !!naEspera;
  const travado = jaConfirmado || naFila;

  /* painel de lotação */
  $('painelEsgotado').hidden = !capacidade.esgotado;
  $('esgotadoNovo').hidden = jaConfirmado || naFila;
  $('esgotadoJa').hidden = !jaConfirmado;
  $('esgotadoNaFila').hidden = jaConfirmado || !naFila;
  $('esgotadoEspera').hidden = jaConfirmado || naFila;
  $('esgotadoDica').hidden = jaConfirmado;
  $('esgotadoFechamento').hidden = jaConfirmado;
  if(naFila && !jaConfirmado){
    $('esgotadoNaFila').textContent =
      'Você já está na lista de espera, na ' + naEspera.posicao + 'ª posição' +
      (naEspera.total > 1 ? ' de ' + naEspera.total : '') +
      '. Se abrir vaga, a organização liga para o número que você deixou.';
  }

  /* o formulário troca de função conforme sobra ou não lugar */
  $('apoioForm').hidden = espera;
  $('apoioEspera').hidden = !espera;
  ['blocoCombo','blocoDeps','blocoRecado','blocoValores'].forEach(id => { $(id).hidden = espera; });
  $('notaEspera').hidden = !espera || naFila;
  $('avisoRodape').hidden = espera;
  $('avisoRodapeEspera').hidden = !espera;

  $('tituloForm').textContent =
    jaConfirmado ? 'Sua presença já está confirmada'
    : naFila     ? 'Você está na lista de espera'
    : espera     ? 'Entre na lista de espera'
    :              'Confirme sua presença';

  $('dicaTel').hidden = !travado;
  if(travado){
    $('dicaTel').textContent = jaConfirmado
      ? 'Este número já confirmou presença. Para alterar ou cancelar, solicite à organização.'
      : 'Este número já está na fila, na ' + naEspera.posicao + 'ª posição.';
  }

  ['nome','combo','recado'].forEach(id => { $(id).disabled = travado; });
  document.querySelectorAll('#listaDeps input, #listaDeps select, #listaDeps .remover')
    .forEach(el => { el.disabled = travado; });

  const semEspacoExtra = (1 + deps.length) >= capacidade.vagas;
  $('btnAdd').disabled = travado || capacidade.esgotado || semEspacoExtra;
  $('btnAdd').textContent = jaConfirmado
    ? 'Confirmação fechada — mudanças só com a organização'
    : (capacidade.esgotado || semEspacoExtra)
      ? 'Sem lugares para mais acompanhantes'
      : '+ Adicionar companheiro(a) ou filho(a)';

  $('btnConfirmar').disabled = ocupado || travado;
  $('btnConfirmar').textContent = ocupado ? 'Salvando...'
    : jaConfirmado ? 'Presença confirmada'
    : naFila       ? 'Você está na fila'
    : espera       ? 'Entrar na lista de espera'
    :                'Confirmar presença';
}
